using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Coordinates;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Events;
using Astronomy.MediaFactory.Core.KnowledgeFoundation.TypedDomains.Measurements;
namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Validation.Events;
public sealed class AstronomyEventParticipantValidationRule:EventRuleBase{public const string Id="event.participants.identity"; public override string RuleId=>Id; public override int Order=>400; protected override IEnumerable<AstronomyKnowledgeValidationIssue> ValidateTyped(AstronomyEventPayload p,AstronomyKnowledgeValidationContext c){var parts=p.Event.Participants; if(parts.GroupBy(x=>(x.Entity.EntityId,x.Role)).Any(g=>g.Count()>1)) yield return Issue(AstronomyEventValidationCodes.ParticipantDuplicate,"Participants must be unique by entity reference and role.","$.event.participants",RuleId); if(parts.Any(x=>!Enum.IsDefined(x.Role))) yield return Issue(AstronomyEventValidationCodes.ParticipantRoleInvalid,"Participant role must be defined.","$.event.participants",RuleId); var primary=parts.Count(x=>x.Role==AstronomyEventParticipantRole.Primary); if(primary!=1) yield return Issue(AstronomyEventValidationCodes.ParticipantPrimaryInvalid,"Exactly one primary participant is required.","$.event.participants",RuleId);}}
